begin;
create schema castly_api_test;
create function castly_api_test.eq(actual bigint,expected bigint,label text) returns void language plpgsql as $$begin if actual is distinct from expected then raise exception 'FAIL % expected %, got %',label,expected,actual;end if;raise notice 'PASS %',label;end$$;
create function castly_api_test.denied(statement text,label text) returns void language plpgsql as $$begin begin execute statement;exception when insufficient_privilege then raise notice 'PASS %',label;return;end;raise exception 'FAIL % unauthorized operation succeeded',label;end$$;
grant usage on schema castly_api_test to anon,authenticated,castly_api;
grant execute on all functions in schema castly_api_test to anon,authenticated,castly_api;
insert into auth.users(id,raw_user_meta_data) values ('00000000-0000-0000-0000-000000000011','{"display_name":"Client"}'),('00000000-0000-0000-0000-000000000012','{"display_name":"Talent"}'),('00000000-0000-0000-0000-000000000013','{"display_name":"Other client"}');
update public.users set primary_role='client' where id in ('00000000-0000-0000-0000-000000000011','00000000-0000-0000-0000-000000000013');
update public.users set primary_role='talent' where id='00000000-0000-0000-0000-000000000012';
insert into public.talent_profiles(id,display_name,category_id,city,day_rate,published) values('00000000-0000-0000-0000-000000000012','Talent','actors','Mumbai',18000,true);
select castly_api_test.eq((select count(*) from pg_roles where rolname='castly_api' and not rolsuper and not rolbypassrls and not rolcreatedb and not rolcreaterole and not rolinherit),1,'dedicated role is not privileged');
select castly_api_test.eq((select count(*) from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename in ('messages','bookings','conversations')),3,'participant tables are in Realtime publication');
select castly_api_test.eq(has_function_privilege('authenticated','public.respond_to_booking(uuid,text)','execute')::int,0,'old decision RPC disabled');
select castly_api_test.eq(has_function_privilege('authenticated','public.cancel_booking(uuid)','execute')::int,0,'old cancellation RPC disabled');
select castly_api_test.eq(has_function_privilege('authenticated','public.complete_onboarding(public.account_role,text)','execute')::int,0,'old onboarding RPC disabled');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000011',true);
set local role authenticated;
select castly_api_test.denied($$update public.users set display_name='Forged'$$,'direct account write disabled');
select castly_api_test.denied($$insert into public.bookings(client_id,talent_id,project_type,proposed_date,location,requirements,indicative_budget) values(auth.uid(),'00000000-0000-0000-0000-000000000012','Shoot',current_date+1,'Mumbai','Detailed brief',1)$$,'direct booking write disabled');
select castly_api_test.denied($$insert into public.messages(conversation_id,sender_id,body) values(gen_random_uuid(),auth.uid(),'Bypass')$$,'direct message write disabled');
select castly_api_test.denied($$insert into public.saved_talent(user_id,talent_id) values(auth.uid(),'00000000-0000-0000-0000-000000000012')$$,'direct favourite write disabled');
select castly_api_test.denied($$update public.talent_profiles set bio='Bypass'$$,'direct talent edit disabled');
reset role;
set local role castly_api;
insert into public.bookings(client_id,talent_id,project_type,proposed_date,location,requirements,indicative_budget) values(auth.uid(),'00000000-0000-0000-0000-000000000012','Shoot',current_date+1,'Mumbai','Detailed creative brief',18000);
select castly_api_test.eq((select count(*) from public.bookings),1,'API can create own client request');
select castly_api_test.denied($$update public.bookings set status='accepted'$$,'client cannot accept own request even through API DB role');
select castly_api_test.denied($$update public.bookings set agreed_rate=1$$,'API role cannot modify protected agreed rate');
select castly_api_test.denied($$insert into public.subscription_entitlements(user_id,entitlement) values(auth.uid(),'forged')$$,'API role cannot grant subscriptions');
select castly_api_test.denied($$select * from auth.users$$,'API role cannot read Auth directory');
select castly_api_test.eq((select count(*) from public.users),1,'API private accounts remain self-only');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000012',true);
set local role castly_api;
update public.bookings set status='accepted';
insert into public.conversations(client_id,talent_id) values('00000000-0000-0000-0000-000000000011',auth.uid());
insert into public.messages(conversation_id,sender_id,body) select id,auth.uid(),'Hello client' from public.conversations;
select castly_api_test.eq((select count(*) from public.messages),1,'relevant talent can send');
select castly_api_test.denied($$insert into public.messages(conversation_id,sender_id,body) select id,'00000000-0000-0000-0000-000000000011','Forged sender' from public.conversations$$,'API cannot impersonate sender');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000013',true);
set local role castly_api;
select castly_api_test.eq((select count(*) from public.bookings),0,'outsider cannot read booking');
select castly_api_test.eq((select count(*) from public.conversations),0,'outsider cannot read conversation');
select castly_api_test.eq((select count(*) from public.messages),0,'outsider cannot read messages');
reset role;
set local role authenticated;
select castly_api_test.eq((select count(*) from public.messages),0,'Realtime RLS excludes outsider');
reset role;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000011',true);
set local role authenticated;
select castly_api_test.eq((select count(*) from public.messages),1,'Realtime RLS includes participant');
reset role;
set local role castly_api;
update public.bookings set status='cancelled';
select castly_api_test.denied($$insert into public.messages(conversation_id,sender_id,body) select id,auth.uid(),'After cancellation' from public.conversations$$,'message writes stop after cancellation');
select castly_api_test.eq((select count(*) from public.messages),1,'history retained after cancellation');
rollback;
